const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Northern Lapland, Sweden: bounding box
  var roi = ee.Geometry.Rectangle([15.0, 67.0, 24.0, 69.0]); // Adjust if needed

  // Dates
  var septStart = '2016-09-01';
  var septEnd = '2016-09-30';
  var octDate = '2016-10-10';

  // Function to mask clouds in Sentinel-2
  function maskS2clouds(image) {
    var qa = image.select('QA60');
    var cloudBitMask = 1 << 10;
    var cirrusBitMask = 1 << 11;
    var mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to compute yellowness index: (Red + Green) / (2 * Blue)
  function addYI(image) {
    var red = image.select('B4');
    var green = image.select('B3');
    var blue = image.select('B2');
    var yi = red.add(green).divide(blue.multiply(2));
    return image.addBands(yi.rename('YI'));
  }

  // 2. Data Acquisition for September 2016 (median composite)
  var s2ColSept = ee.ImageCollection('COPERNICUS/S2_SR')
                    .filterBounds(roi)
                    .filterDate(septStart, septEnd)
                    .map(maskS2clouds)
                    .map(addYI);

  // Check if collection is empty
  var septSize = s2ColSept.size().getInfo();
  if (septSize === 0) {
    // Try Landsat 8 as fallback for September
    var landsatColSept = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
                          .filterBounds(roi)
                          .filterDate(septStart, septEnd)
                          .map(function(image) {
                            // Scale factors for Landsat 8
                            var opticalBands = image.select(['SR_B4', 'SR_B3', 'SR_B2']).multiply(0.0000275).add(-0.2);
                            return image.addBands(opticalBands, null, true);
                          });
    var landsatSeptSize = landsatColSept.size().getInfo();
    if (landsatSeptSize === 0) {
      print("September 2016: No images found (Sentinel-2 and Landsat 8).");
      print("<answer>C1</answer>");
      return;
    }
    // Create median composite for Landsat
    var septImage = landsatColSept.median();
    // Add YI for Landsat (bands: B4=red, B3=green, B2=blue)
    var redL = septImage.select('SR_B4');
    var greenL = septImage.select('SR_B3');
    var blueL = septImage.select('SR_B2');
    var yiL = redL.add(greenL).divide(blueL.multiply(2));
    septImage = septImage.addBands(yiL.rename('YI'));
    print("September 2016: Landsat 8 composite, images: " + landsatSeptSize);
  } else {
    // Use Sentinel-2 median composite
    var septImage = s2ColSept.median();
    print("September 2016: Sentinel-2 composite, images: " + septSize);
  }

  // 3. Data Acquisition for October 10, 2016
  var s2ColOct = ee.ImageCollection('COPERNICUS/S2_SR')
                  .filterBounds(roi)
                  .filterDate(octDate, octDate)
                  .map(maskS2clouds)
                  .map(addYI);

  var octSize = s2ColOct.size().getInfo();
  if (octSize === 0) {
    // Try Landsat 8 for October 10
    var landsatColOct = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
                        .filterBounds(roi)
                        .filterDate(octDate, octDate)
                        .map(function(image) {
                          var opticalBands = image.select(['SR_B4', 'SR_B3', 'SR_B2']).multiply(0.0000275).add(-0.2);
                          return image.addBands(opticalBands, null, true);
                        });
    var landsatOctSize = landsatColOct.size().getInfo();
    if (landsatOctSize === 0) {
      print("October 10, 2016: No images found (Sentinel-2 and Landsat 8).");
      print("<answer>C1</answer>");
      return;
    }
    var octImage = landsatColOct.median();
    var redL = octImage.select('SR_B4');
    var greenL = octImage.select('SR_B3');
    var blueL = octImage.select('SR_B2');
    var yiL = redL.add(greenL).divide(blueL.multiply(2));
    octImage = octImage.addBands(yiL.rename('YI'));
    print("October 10, 2016: Landsat 8 image, images: " + landsatOctSize);
  } else {
    var octImage = s2ColOct.median();
    print("October 10, 2016: Sentinel-2 image, images: " + octSize);
  }

  // 4. Check valid pixels for YI band
  var septCount = septImage.select('YI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).get('YI').getInfo();

  var octCount = octImage.select('YI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).get('YI').getInfo();

  if (septCount === 0 || octCount === 0) {
    print("No valid pixels after masking. September count: " + septCount + ", October count: " + octCount);
    print("<answer>C2</answer>");
    return;
  }

  // 5. Compute mean YI
  var septMean = septImage.select('YI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).get('YI').getInfo();

  var octMean = octImage.select('YI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).get('YI').getInfo();

  // 6. Validation
  if (septMean === null || octMean === null || 
      isNaN(septMean) || isNaN(octMean) ||
      septMean < 0 || octMean < 0 || septMean > 10 || octMean > 10) { // Reasonable bounds for YI
    print("Calculation failure. September YI: " + septMean + ", October YI: " + octMean);
    print("<answer>C3</answer>");
    return;
  }

  // 7. Output stats and compare
  print("September 2016 mean YI: " + septMean.toFixed(3) + " (pixels: " + septCount + ")");
  print("October 10, 2016 mean YI: " + octMean.toFixed(3) + " (pixels: " + octCount + ")");

  // If October mean YI > September mean YI, then more yellow areas
  if (octMean > septMean) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
